// iBuffer0: THE BATTLES. Each cell of the grid holds one Pokémon type (see the [Shared GLSL] tab), and
// reads its own last frame. Every other frame, each cell fights two neighbours on opposite sides,
// picked at random, and takes the type of any that beats it.

int cellType(ivec2 cell, ivec2 grid) {
  cell = (cell + grid) % grid;  // The grid wraps around at its edges.
  return typeOf(texelFetch(iBuffer0, cell, 0).r);
}

// The type that holds this cell after `defender` is attacked by `attacker`. The more an attack
// beats the defender's own, the more likely it wins, and [luck] adds chance either way.
int fight(int defender, int attacker, vec2 seed) {
  float advantage = effectiveness(attacker, defender) - effectiveness(defender, attacker);
  float roll = luck * (2. * hash(seed) - 1.);
  return advantage + roll > 0.5 ? attacker : defender;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  ivec2 grid = ivec2(gridSize());
  ivec2 cell = ivec2(fragCoord);
  if (cell.x >= grid.x || cell.y >= grid.y) {
    fragColor = vec4(0.);
    return;
  }
  vec2 uv = vec2(cell) / float(grid.y);
  if (iFrame == 0) {
    // Start with patches of every type.
    fragColor = vec4(fract(4. * fbm(8. * uv)), 0., 0., 1.);
    return;
  }
  float stored = texelFetch(iBuffer0, cell, 0).r;
  if (iFrame % 2 == 1) {
    fragColor = vec4(stored, 0., 0., 1.);
    return;
  }
  float t = float(iFrame) / 60.;
  ivec2 offset = ivec2(floor(3. * vec2(hash(uv + t), hash(uv + t + 10.)))) - 1;
  int type = typeOf(stored);
  type = fight(type, cellType(cell + offset, grid), uv + t + 20.);
  type = fight(type, cellType(cell - offset, grid), uv + t + 30.);
  fragColor = vec4(store(type), 0., 0., 1.);
}

