// CANVAS2D: a legend for the types, drawn over the battle. Switch off "Draw over the image" above
// to hide it.
const TYPES = [
  ["Normal", [0.886, 0.867, 0.757]], ["Fire", [0.995, 0.509, 0.000]], ["Water", [0.020, 0.412, 0.780]],
  ["Electric", [0.992, 0.961, 0.051]], ["Grass", [0.203, 0.750, 0.095]], ["Ice", [0.760, 0.865, 0.848]],
  ["Fighting", [0.630, 0.080, 0.122]], ["Poison", [0.734, 0.064, 0.775]], ["Ground", [0.770, 0.592, 0.415]],
  ["Flying", [0.575, 0.654, 1.000]], ["Psychic", [1.000, 0.431, 0.527]], ["Bug", [0.729, 1.000, 0.612]],
  ["Rock", [0.670, 0.354, 0.210]], ["Ghost", [0.514, 0.117, 0.730]], ["Dragon", [0.195, 0.193, 0.895]],
  ["Dark", [0.125, 0.125, 0.125]], ["Steel", [0.595, 0.595, 0.595]], ["Fairy", [1.000, 0.722, 0.992]],
];
const COLUMNS = 6;

// The same colours as typeColors in the [Shared GLSL] tab, as CSS colours.
const css = ([r, g, b]) => `rgb(${r * 255}, ${g * 255}, ${b * 255})`;

// Nothing moves, so it's drawn once, on the first step, and the canvas keeps it.
function draw(ctx, {frame, width, height}) {
  if (frame > 0) return;
  const rows = Math.ceil(TYPES.length / COLUMNS);
  const cell = {w: (width - 80) / COLUMNS, h: 44};
  const top = height - 40 - rows * cell.h;

  ctx.fillStyle = "rgba(10, 10, 20, 0.72)";
  ctx.beginPath();
  ctx.roundRect(20, top - 20, width - 40, rows * cell.h + 40, 24);
  ctx.fill();

  ctx.font = "500 27px Inter";
  ctx.textBaseline = "middle";
  TYPES.forEach(([name, color], i) => {
    const x = 40 + (i % COLUMNS) * cell.w;
    const y = top + Math.floor(i / COLUMNS) * cell.h + cell.h / 2;
    ctx.fillStyle = css(color);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.6)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x + 12, y, 12, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "white";
    ctx.fillText(name, x + 34, y + 1);
  });
}
